<?php
require_once __DIR__ . '/auth.php'; require_login(); require_once __DIR__ . '/monitor_lib.php';
$trash='../data/lixeira_noticias.json'; $nf='../data/noticias.json'; $items=tvs_read_json_file($trash);
if(isset($_GET['restore'])){ $id=$_GET['restore']; $restored=null; $keep=[]; foreach($items as $it){ if(($it['id']??'')===$id){ unset($it['deleted_at']); $restored=$it; } else $keep[]=$it; } if($restored){ $news=tvs_read_json_file($nf); $news[]=$restored; tvs_save_json_file($nf,$news); tvs_save_json_file($trash,$keep); } header('Location: lixeira.php?restored=1'); exit; }
if(isset($_GET['delete'])){ $id=$_GET['delete']; $items=array_values(array_filter($items,fn($i)=>($i['id']??'')!==$id)); tvs_save_json_file($trash,$items); header('Location: lixeira.php?deleted=1'); exit; }
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Lixeira</title><link rel="stylesheet" href="admin.css?v=10"></head><body><div class="admin"><aside class="side"><div class="logo"><img src="../assets/logo-tv-sumare.jpeg"><div><b>TV SUMARÉ</b><br><small>Painel</small></div></div><nav class="menu"><a href="index.php">Dashboard</a><a href="noticias.php">Notícias publicadas</a><a class="active" href="lixeira.php">Lixeira</a><a href="logout.php">Sair</a></nav></aside><main class="main"><h1>Lixeira de notícias</h1><?php if(isset($_GET['restored'])): ?><div class="notice">Notícia restaurada.</div><?php endif; ?><?php if(!$items): ?><div class="box">Lixeira vazia.</div><?php endif; ?><?php foreach(array_reverse($items) as $n): ?><div class="box" style="margin-top:12px"><small>Apagada em <?=htmlspecialchars(date('d/m/Y H:i', strtotime($n['deleted_at']??'now')))?></small><h2><?=htmlspecialchars($n['title']??'Sem título')?></h2><p><?=htmlspecialchars($n['subtitle']??'')?></p><a class="btn orange" href="?restore=<?=urlencode($n['id']??'')?>">Restaurar</a> <a class="btn danger" onclick="return confirm('Excluir definitivamente?')" href="?delete=<?=urlencode($n['id']??'')?>">Excluir definitivamente</a></div><?php endforeach; ?></main></div></body></html>
